package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import java.util.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;

/** 原SDK只读properties；中心展开固定文档本地引用，原文仍保存在不可变版本中。 */
final class ToolOpenApi {
 static final Set<String> METHODS=Set.of("get","post","put","delete","patch","head","options","trace");
 static JSONObject operation(JSONObject api,JSONObject path,JSONObject raw){var result=copy(ToolJsonSchema.dereference(api,raw));var parameters=new JSONArray();if(path.get("parameters") instanceof JSONArray inherited)parameters.addAll(inherited);if(result.get("parameters") instanceof JSONArray own)parameters.addAll(own);if(!parameters.isEmpty()){var merged=new LinkedHashMap<String,JSONObject>();for(Object value:parameters){if(!(value instanceof JSONObject p))throw error("工具参数引用形状错误",422);p=copy(ToolJsonSchema.dereference(api,p));merged.put(p.getString("in")+":"+p.getString("name"),p);}result.put("parameters",new JSONArray(merged.values()));}if(result.get("requestBody") instanceof JSONObject body)result.put("requestBody",copy(ToolJsonSchema.dereference(api,body)));if(result.get("responses") instanceof JSONObject responses){var resolved=new JSONObject();for(var field:responses.entrySet()){if(!(field.getValue() instanceof JSONObject response))throw error("工具响应引用形状错误",422);resolved.put(field.getKey(),copy(ToolJsonSchema.dereference(api,response)));}result.put("responses",resolved);}return result;}
 static JSONObject publicApi(JSONObject api){var result=copy(api);result.remove("servers");var paths=api.getJSONObject("paths");var output=new JSONObject();for(var entry:paths.entrySet()){var path=ToolJsonSchema.dereference(api,(JSONObject)entry.getValue());var methods=new JSONObject();for(var field:path.entrySet())if(METHODS.contains(field.getKey())){var op=operation(api,path,(JSONObject)field.getValue());op.remove("servers");var params=op.getJSONArray("parameters");if(params!=null){params.removeIf(v->authentication((JSONObject)v,field.getKey()));for(Object raw:params){var p=(JSONObject)raw;p.put("schema",schema(api,p.getJSONObject("schema"),new HashSet<>(),0));}}var body=op.getJSONObject("requestBody");if(body!=null)schemas(api,body.getJSONObject("content"));var responses=op.getJSONObject("responses");if(responses!=null)for(Object raw:responses.values())schemas(api,((JSONObject)raw).getJSONObject("content"));methods.put(field.getKey(),op);}output.put(entry.getKey(),methods);}result.put("paths",output);return result;}
 private static boolean authentication(JSONObject p,String method){if(!"header".equals(p.get("in"))||!"Authorization".equals(p.get("name")))return false;String v=p.getJSONObject("schema").getString("default");return "MD5".equals(v)&&"get".equals(method)||v!=null&&v.startsWith("HMAC:");}
 private static void schemas(JSONObject api,JSONObject content){if(content!=null)for(Object raw:content.values()){var media=(JSONObject)raw;if(media.get("schema") instanceof JSONObject s)media.put("schema",schema(api,s,new HashSet<>(),0));}}
 static JSONObject schema(JSONObject root,JSONObject raw,Set<String> visiting,int depth){if(raw==null||depth>48)throw error("工具SDK Schema展开过深",422);var result=copy(raw);String ref=result.getString("$ref");if(ref!=null){if(!visiting.add(ref))return result;Object target=ToolJsonSchema.pointer(root,ref);if(!(target instanceof JSONObject s))throw error("原Link Schema引用非对象",422);result=schema(root,s,visiting,depth+1);visiting.remove(ref);return result;}
  if(result.get("properties") instanceof JSONObject properties)for(var field:new ArrayList<>(properties.entrySet()))if(field.getValue() instanceof JSONObject s)properties.put(field.getKey(),schema(root,s,visiting,depth+1));if(result.get("items") instanceof JSONObject item)result.put("items",schema(root,item,visiting,depth+1));
  // allOf各约束仍保留给中心Draft7验证，同时暴露SDK所需的确定properties/default。
  for(String keyword:List.of("allOf","anyOf","oneOf"))if(result.get(keyword) instanceof JSONArray branches){var merged=result.getJSONObject("properties");if(merged==null)merged=new JSONObject();var resolved=new JSONArray();int count=branches.size();var occurrences=new HashMap<String,Integer>();for(Object value:branches){if(!(value instanceof JSONObject s))throw error("工具组合Schema无效",422);var branch=schema(root,s,visiting,depth+1);resolved.add(branch);if(branch.get("properties") instanceof JSONObject p)for(var field:p.entrySet()){occurrences.merge(field.getKey(),1,Integer::sum);Object old=merged.get(field.getKey());merged.put(field.getKey(),old==null?field.getValue():mergeProperty((JSONObject)old,(JSONObject)field.getValue(),keyword));}if(!result.containsKey("type")&&branch.containsKey("type"))result.put("type",branch.get("type"));}if(!"allOf".equals(keyword))for(var field:merged.entrySet())if(((JSONObject)field.getValue()).containsKey("default")&&occurrences.getOrDefault(field.getKey(),0)!=count)throw error("原SDK无法确定分支独有默认值，须提供一致组装Schema",422);result.put(keyword,resolved);if(!merged.isEmpty())result.put("properties",merged);}
  return result;
 }
 private static JSONObject mergeProperty(JSONObject first,JSONObject second,String keyword){if(ToolSchema.same(first,second))return first;if(!ToolSchema.same(first.get("default"),second.get("default"))||first.containsKey("default")!=second.containsKey("default")||!Objects.equals(first.getOrDefault("x-from",0),second.getOrDefault("x-from",0))||"object".equals(first.get("type"))!="object".equals(second.get("type")))throw error("工具SDK同名组合属性组装语义不确定",422);var result=new JSONObject();if(first.containsKey("default"))result.put("default",first.get("default"));result.put("x-from",first.getOrDefault("x-from",0));if("object".equals(first.get("type"))){result.put("type","object");var properties=new JSONObject();for(JSONObject item:List.of(first,second))if(item.get("properties") instanceof JSONObject p)for(var field:p.entrySet()){Object old=properties.get(field.getKey());properties.put(field.getKey(),old==null?field.getValue():mergeProperty((JSONObject)old,(JSONObject)field.getValue(),keyword));}result.put("properties",properties);}result.put(keyword,new JSONArray(List.of(first,second)));return result;}
 static JSONObject copy(JSONObject value){return JSON.parseObject(value.toJSONString(JSONWriter.Feature.WriteMapNullValue));}
 static JSONObject publicOperation(JSONObject api,String operationId){var result=publicApi(api);var paths=result.getJSONObject("paths");for(String name:new ArrayList<>(paths.keySet())){var path=paths.getJSONObject(name);path.entrySet().removeIf(e->!(e.getValue() instanceof JSONObject o)||!Objects.equals(operationId,o.get("operationId")));if(path.isEmpty())paths.remove(name);}return result;}
}
